customer_success_rate = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=(100.0 * COUNT(transactions_made.WHERE(LOWER(status) == 'success')) / COUNT(transactions_made))
).ORDER_BY(success_rate.ASC())

customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == 'success')) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

active_customers_since_2023 = Customers.WHERE(
    (join_date >= "2023-01-01") & (LOWER(status) == "active")
)
country_tac = active_customers_since_2023.PARTITION(
    name="country_groups", by=country
).CALCULATE(country=country, TAC=COUNT(Customers))

prices_in_last_7_days = DailyPrices.WHERE(DATEDIFF("days", date, DATETIME('now')) <= 6)

acp_by_ticker_type = prices_in_last_7_days.CALCULATE(
    type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=type
).CALCULATE(
    ticker_type=type,
    average_closing_price=AVG(prices_in_last_7_days.close)
)

top_transaction_types = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="type_groups", by=transaction_type
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

